contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept two addresses and an amount to send when invoking withdraw via getFirstWithdrawalBonus (the contract C will send to recipient).
    // recipient: the address to receive the bonus (an address controlled by this test via fallback/receive).
    // callTwice: if true we will attempt to call getFirstWithdrawalBonus twice to observe revert behavior on the second call.
    function run(address payable recipient, bool callTwice) public payable {
        require(address(this).balance >= 0); // no precondition on inputs

        // Ensure the recipient is this contract so we can observe Ether coming in
        // but allow any recipient per the parameters — we will only assert properties when recipient == address(this)

        // Read initial balances
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        bool revertedFirst;
        try c.getFirstWithdrawalBonus(recipient) {
            revertedFirst = false;
        } catch {
            revertedFirst = true;
        }

        bool revertedSecond = false;
        if (callTwice) {
            try c.getFirstWithdrawalBonus(recipient) {
                revertedSecond = false;
            } catch {
                revertedSecond = true;
            }
        }

        uint afterThis = address(this).balance;
        uint afterC = address(c).balance;

        // Observe whether recipient was this contract: if so, we can state exact Ether movement
        // General rule asserted below covers both cases: either first call reverts, or it succeeds and transfers exactly 100 wei to recipient,
        // and the second call (if attempted) must revert (cannot grant bonus twice).

        // The assert encodes: if first call succeeded then contract C lost 100 wei and recipient gained 100 wei, and if a second call was made then it must revert.
        assert(
            (
                // Case A: first call reverted => nothing guaranteed about balances but second (if attempted) may or may not revert
                revertedFirst
            ) || (
                // Case B: first call succeeded => C balance decreased by 100 and if recipient==this then this gained 100, and second call (if attempted) reverted
                (!revertedFirst
                    && address(c).balance + 100 == beforeC
                    && (recipient != address(this) || afterThis == beforeThis + 100)
                    && (!callTwice || revertedSecond)
                )
            )
        );
    }

    // Accept Ether sent from C when withdrawReward is invoked
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a recipient and a flag indicating whether to attempt the second call.
    function run(address payable recipient, bool attemptSecond) public payable {
        require(true);

        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        bool firstReverted;
        // first call must be a top-level statement
        try c.getFirstWithdrawalBonus(recipient) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool secondReverted = false;
        if (attemptSecond) {
            // second call also top-level
            try c.getFirstWithdrawalBonus(recipient) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
        }

        uint afterThis = address(this).balance;
        uint afterC = address(c).balance;

        // Assert the general invariant:
        // Either the first call reverted, or it succeeded and transferred exactly 100 wei out of C,
        // and if recipient is this contract then this contract's balance rose by 100,
        // and any attempted second call must revert (cannot claim bonus twice in same transaction).
        assert(
            firstReverted
            || (
                !firstReverted
                && afterC + 100 == beforeC
                && (recipient != address(this) || afterThis == beforeThis + 100)
                && (!attemptSecond || secondReverted)
            )
        );
    }

    // Allow receiving Ether from C
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a recipient and a flag whether to attempt an immediate withdrawReward after the bonus
    function run(address payable recipient, bool tryImmediateWithdraw) public payable {
        require(true);

        // Record balances before any calls
        uint beforeC = address(c).balance;
        uint beforeRecipient = recipient == address(this) ? address(this).balance : 0;

        bool firstReverted;
        // first call must be top-level
        try c.getFirstWithdrawalBonus(recipient) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool withdrawReverted = false;
        uint afterRecipient = beforeRecipient;
        uint afterC = address(c).balance;

        if (tryImmediateWithdraw) {
            // attempt to call withdrawReward immediately; must be top-level
            try c.withdrawReward(recipient) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
            // observe balances if recipient is this contract
            if (recipient == address(this)) {
                afterRecipient = address(this).balance;
            }
            afterC = address(c).balance;
        }

        // General rule:
        // If the initial getFirstWithdrawalBonus reverted, nothing can be assumed about balances here.
        // Otherwise it succeeded and any net transfer out of C as a result of these calls (observed
        // as beforeC - afterC) is at most 100 wei, and if recipient is this contract then the recipient
        // balance increased by at most 100 wei. Also, if a second explicit withdrawReward was attempted
        // immediately after, it either reverted or did not transfer additional funds (i.e., afterC did not decrease further).
        assert(
            firstReverted
            || (
                // C lost at most 100 wei overall
                beforeC >= afterC && beforeC - afterC <= 100
                // if recipient is this test contract, it gained at most 100 wei
                && (recipient != address(this) || afterRecipient >= beforeRecipient && afterRecipient - beforeRecipient <= 100)
                // if withdrawReward was attempted immediately, either it reverted or it did not further reduce C's balance
                && (!tryImmediateWithdraw || withdrawReverted || (afterC == address(c).balance))
            )
        );
    }

    // allow receiving Ether
    receive() external payable {}
}

