    // Try calling getFirstWithdrawalBonus, optionally then calling withdrawReward for the same recipient.
    function run(address payable recipient, bool tryImmediateWithdraw) public payable {
        require(true);

        // Record balances before any calls
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool bonusReverted;
        // top-level state-changing call: attempt to give the first-withdrawal bonus
        try c.getFirstWithdrawalBonus(recipient) {
            bonusReverted = false;
        } catch {
            bonusReverted = true;
        }

        bool withdrawReverted = false;
        // If requested, attempt an immediate explicit withdrawReward(recipient)
        if (tryImmediateWithdraw) {
            try c.withdrawReward(recipient) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General invariant asserted for all inputs and outcomes:
        // Either the initial bonus call reverted, or otherwise:
        // - C's balance decreased by at most 100 wei overall (beforeC - afterC <= 100)
        // - This test contract (if it is the recipient) gained at most 100 wei (afterThis - beforeThis <= 100)
        // - If an immediate withdrawReward was attempted, it did not cause additional net outflow beyond that at-most-100 (i.e., afterC is not less than it would already be)
        assert(
            bonusReverted
            || (
                beforeC >= afterC && beforeC - afterC <= 100
                && afterThis >= beforeThis && afterThis - beforeThis <= 100
                && (!tryImmediateWithdraw || withdrawReverted || true)
            )
        );
    }

    // allow receiving Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try calling getFirstWithdrawalBonus on some recipient and observe balances and _locked.
    function run(address payable recipient) public payable {
        require(true);

        // record balances before the call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool callReverted;
        // top-level state-changing call: attempt to give the first-withdrawal bonus
        try c.getFirstWithdrawalBonus(recipient) {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        // read observable values after the call
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        bool locked = c._locked();

        // Assert the general rule for all inputs and outcomes:
        // Either the call reverted, or otherwise:
        // - C's balance decreased by at most 100 wei
        // - This test contract (if recipient) gained at most 100 wei
        // - C's public _locked flag is false (no permanent lock)
        assert(
            callReverted
            || (
                beforeC >= afterC && beforeC - afterC <= 100
                && (recipient != payable(address(this)) || afterThis >= beforeThis) && (recipient != payable(address(this)) || afterThis - beforeThis <= 100)
                && locked == false
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call getFirstWithdrawalBonus for a chosen recipient address (addr).
    // Because C uses internal state we cannot read directly, we rely on observable effects:
    // - c._locked() is public in SmartFix so we can observe it to ensure non-reentrant lock resets.
    // - address(c).balance observes Ether moved out by withdrawReward.
    // - getFirstWithdrawalBonus may revert; we capture that.

    function run(address payable recipient) public payable {
        require(recipient != address(0));

        // record balance of contract before the call
        uint balBefore = address(c).balance;
        bool reverted;
        bool lockedBefore = c._locked();

        // perform the call and capture revert status
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        bool lockedAfter = c._locked();

        // General rule asserted:
        // If the call did not revert, then (1) the contract's _locked flag is false after the call
        // (non-reentrancy unlocked), and (2) the contract's balance decreased by at most 100
        // (the bonus payment), and (3) the function's observable effect is that the contract paid out
        // at most 100 wei (could be 0 if withdrawReward sent nothing), i.e., balBefore - balAfter <= 100.
        // If the call reverted, we do not assert balance change but we still assert that locked state is not left true.

        assert(lockedAfter == false && (reverted || balBefore >= balAfter) && (reverted || (balBefore - balAfter) <= 100));
    }

    receive() external payable {}
}

